Command: curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{"query": "query { projects(filter: {name: {contains: "Checkout Redesign"}}) { nodes { id name identifier } } }"}'
